```javascript
// rateLimiter.js
const requestCounts = new Map();

function rateLimiter(req, res, next) {
  const ip = req.ip;
  const now = Date.now();

  // Get the existing timestamps for this IP or create a new array
  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, []);
  }

  const timestamps = requestCounts.get(ip);

  // Remove timestamps older than 1 second (1000 ms)
  const validTimestamps = timestamps.filter(ts => now - ts < 1000);
  requestCounts.set(ip, validTimestamps);

  // Check if limit is exceeded
  if (validTimestamps.length >= 5) {
    // Calculate retry-after value (first allowed timestamp + 1 second - now)
    const oldestTimestamp = validTimestamps[0];
    const retryAfter = Math.ceil((oldestTimestamp + 1000 - now) / 1000);
    res.set('Retry-After', String(retryAfter));
    return res.status(429).json({ error: 'Too many requests, please try again later.' });
  }

  // Add current timestamp and proceed
  validTimestamps.push(now);
  next();
}

module.exports = rateLimiter;
```

